// Generated by `npm run setup` from the local Minecraft jar. If this import fails, run setup.
import manifest from '../../public/mc/manifest.json';

const ITEMS = new Set<string>(manifest.items);
const BLOCKS = new Set<string>(manifest.blocks);

export const MC_VERSION: string = manifest.version;

export type ItemLook =
  | {kind: 'sprite'; id: string}
  | {kind: 'block'; top: string; side: string; front: string};

/**
 * How an item id is drawn in a slot. Flat items use item/<id>.png; block items
 * (oak_planks, ancient_debris...) have no item sprite and are drawn as a small cube.
 * Unknown ids throw, so a typo fails the render instead of showing an empty slot.
 */
export const resolveItem = (id: string): ItemLook => {
  if (ITEMS.has(id)) return {kind: 'sprite', id};
  const pick = (...names: string[]) => names.find((n) => BLOCKS.has(n));
  const side = pick(`${id}_side`, id, `${id}_front`);
  if (side) {
    const top = pick(`${id}_top`, id, side)!;
    const front = pick(`${id}_front`, side)!;
    return {kind: 'block', top, side, front};
  }
  throw new Error(`Unknown Minecraft item or block id "${id}" (Minecraft ${MC_VERSION}). Check public/mc/textures/item and block.`);
};
